    }, []);
    return section;
}

export function App() {
    const section = useHashSection();
    const [orders, setOrders] = React.useState<Order[]>(() => generateOrders());
    const [collapsed, setCollapsed] = useStoredState(
        'admin.sidebar.collapsed',
        () => window.innerWidth < 960,
