.group-head__sum {
    color: var(--g-color-text-secondary);
    font-variant-numeric: tabular-nums;
}

/* ---------- column drag & drop ---------- */
.col-head {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    max-width: 100%;
    margin-inline-start: -16px;
    padding: 2px 4px;
    border-radius: var(--g-border-radius-xs);
    cursor: grab;
    user-select: none;
}

.g-table__cell_align_end .col-head {
    margin-inline-start: 0;
}

.col-head:focus-visible {
    outline: 2px solid var(--g-color-line-focus);
}

.col-head__grip {
    flex: none;
    opacity: 0;
    color: var(--g-color-text-hint);
    transition: opacity 0.1s;
}

.col-head:hover .col-head__grip,
.col-head:focus-visible .col-head__grip,
.col-head_dragging .col-head__grip {
    opacity: 1;
}

.col-head__title {
    overflow: hidden;
    text-overflow: ellipsis;
}

.orders-page__table_dragging,
.orders-page__table_dragging * {
    cursor: grabbing;
}

.orders-table .orders-table__cell_dragging {
    opacity: 0.4;
}

.orders-table .orders-table__cell_drop-before {
    box-shadow: inset 2px 0 0 var(--g-color-line-brand);
}

.orders-table .orders-table__cell_drop-after {
    box-shadow: inset -2px 0 0 var(--g-color-line-brand);
}

[dir='rtl'] .orders-table .orders-table__cell_drop-before {
    box-shadow: inset -2px 0 0 var(--g-color-line-brand);
}

[dir='rtl'] .orders-table .orders-table__cell_drop-after {
    box-shadow: inset 2px 0 0 var(--g-color-line-brand);
}

