args.command:
(npx vite --port 5199 --strictPort > /tmp/vite.log 2>&1 &) ; sleep 3; cat /tmp/vite.log | tail -3
mkdir -p /tmp/pwscripts && cat > /tmp/pwscripts/shot.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error' || m.type()==='warning') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
await page.goto('http://localhost:5199/');
await page.waitForSelector('.orders-table');
await page.screenshot({ path: '/tmp/pwscripts/1-initial.png' });
// select some rows
const rows = page.locator('.orders-table__row_order');
await rows.nth(0).click();
await rows.nth(3).click({ modifiers: ['Shift'] });
await page.screenshot({ path: '/tmp/pwscripts/2-selected.png' });
console.log('selected', await page.locator('.orders-table__row_selected').count());
// drag column "Сумма" before "Дата"
const src = page.locator('[data-col-id="amount"]');
const dst = page.locator('th:has([data-col-id="createdAt"])');
const before = await page.locator('[data-col-id]').evaluateAll(els => els.map(e => e.dataset.colId));
await src.dragTo(dst, { targetPosition: { x: 5, y: 10 } });
const after = await page.locator('[data-col-id]').evaluateAll(els => els.map(e => e.dataset.colId));
console.log('before', before.join(','), '\nafter ', after.join(','));
// collapse group
await page.locator('.orders-table__row_group').first().click();
// collapse sidebar
await page.locator('.sidebar__toggle').click();
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/pwscripts/3-after.png' });
// keyboard move
await page.locator('[data-col-id="amount"]').focus();
await page.keyboard.press('Alt+ArrowRight');
const kb = await page.locator('[data-col-id]').evaluateAll(els => els.map(e => e.dataset.colId));
console.log('kb    ', kb.join(','), 'focused:', await page.evaluate(() => document.activeElement?.dataset?.colId));
// column setup popup
await page.getByRole('button', { name: 'Колонки' }).click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/pwscripts/4-setup.png' });
await page.keyboard.press('Escape');
// hover collapsed sidebar
await page.locator('.sidebar__item').nth(1).hover();
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/pwscripts/5-tooltip.png', clip: { x: 0, y: 0, width: 400, height: 300 } });
// grouping off + horizontal scroll check at narrow width
await page.setViewportSize({ width: 900, height: 700 });
await page.locator('.g-switch').click();
await page.locator('.orders-table').evaluate(el => { el.scrollLeft = 300; el.scrollTop = 400; });
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/pwscripts/6-narrow.png' });
console.log('errors:', errors);
await browser.close();
EOF
node /tmp/pwscripts/shot.mjs

