args.command:
cd /tmp/pwscripts && cat > shot2.mjs <<'EOF'
import { chromium } from '/tmp/pw/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ args: ['--no-sandbox','--disable-gpu','--single-process','--no-zygote'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error' || m.type()==='warning') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
await page.goto('http://localhost:5199/#/orders');
await page.evaluate(() => localStorage.clear()); await page.reload();
await page.waitForSelector('.orders-table');
const rows = page.locator('.orders-table__row_order');
await rows.nth(0).click();
await rows.nth(3).click({ modifiers: ['Shift'] });
// start a synthetic drag of "Город" over the left half of "Дата"
await page.evaluate(() => {
  const dt = new DataTransfer();
  const src = document.querySelector('[data-col-id="city"]');
  src.dispatchEvent(new DragEvent('dragstart', { bubbles: true, dataTransfer: dt }));
  window.__dt = dt;
});
await page.waitForTimeout(50);
await page.evaluate(() => {
  const th = document.querySelector('[data-col-id="createdAt"]').closest('th');
  const r = th.getBoundingClientRect();
  th.dispatchEvent(new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: window.__dt, clientX: r.left + 4, clientY: r.top + 10 }));
});
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/pwscripts/7-drag.png' });
await page.evaluate(() => document.querySelector('[data-col-id="city"]').dispatchEvent(new DragEvent('dragend', { bubbles: true })));
await page.locator('.orders-table').evaluate(el => { el.scrollLeft = 0; el.scrollTop = 1500; });
await page.setViewportSize({ width: 1000, height: 700 });
await page.locator('.orders-table').evaluate(el => { el.scrollLeft = 250; });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/pwscripts/8-scrolled.png' });
await page.goto('http://localhost:5199/#/users');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/pwscripts/9-users.png', clip: {x:0,y:0,width:700,height:300} });
console.log('errors:', errors);
await browser.close();
EOF
LD_LIBRARY_PATH=$(cat /tmp/ldpath) FONTCONFIG_FILE=/tmp/fonts.conf timeout 100 node shot2.mjs 2>&1 | head

